#include <cstdio>
#include <cstdlib>

int main() {
    int n = 0;
    if (std::scanf("%d", &n) != 1) return 1;
    if (n < 1 || n > 100) return 1;
    long long total = 0;
    for (int i = 0; i < n; i++) {
        char token[32];
        if (std::scanf("%31s", token) != 1) return 1;
        char* end = nullptr;
        const char* text = token;
        long value = std::strtol(text, &end, 10);
        if (end == text || *end != '\0') return 1;
        if (value < -1000000000L || value > 1000000000L) return 1;
        total += value;
    }
    std::printf("%lld\n", total);
    return 0;
}
